#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> v1 = {1, 2, 3};
    std::vector<int> v2 = {40, 50};

    // O(1) operation
    v1.swap(v2);

    // v1 now contains {40, 50}
    // v2 now contains {1, 2, 3}

    // Swap trick to reduce capacity to size (or zero)
    std::vector<int>(v2).swap(v2); 
    std::cout << "v2 size after swap trick: " << v2.size() << "\n";

    // The global std::swap calls the member function
    std::swap(v1, v2);
}
